INSERT INTO egd (nm, ar, gen, comp, price, bc, cat, rx, form, str, class, uses) VALUES
('1 2 3 (one two three) syrup 120 ml', 'ون تو ثري شراب 120 مل', 'chlorpheniramine+paracetamol+pseudoephedrine', 'hikma pharma', 4000, '6221000003295', 'medication', 'no', 'syrup', '120ml', 'cold products', 'تخفيف أعراض نزلات البرد والإنفلونزا مثل الصداع وارتفاع درجة الحرارة. يساعد في علاج احتقان الأنف والجيوب الأنفية وتحسين التنفس. يخفف سيلان الأنف والعطس الناتج عن الحساسية أو البرد. يقلل آلام الجسم والعضلات المصاحبة لنزلات البرد. يساعد على تهدئة الصداع المرتبط بالبرد أو احتقان الجيوب الأنفية. يساهم في تقليل احمرار ودموع العين الناتجة عن الحساسية. يستخدم لتخفيف أعراض الحساسية الموسمية المصحوبة باحتقان وسيلان الأنف.'),
('1 2 3 (one two three) 20 f.c.tabs', 'ون تو ثري 20 قرص', 'chlorpheniramine+paracetamol+pseudoephedrine', 'hikma pharma', 4000, '6221000000010', 'medication', 'no', 'tablet', NULL, 'cold products', 'تخفيف أعراض نزلات البرد والإنفلونزا مثل الصداع وارتفاع درجة الحرارة. يساعد في علاج احتقان الأنف والجيوب الأنفية وتحسين التنفس. يخفف سيلان الأنف والعطس الناتج عن الحساسية أو البرد. يقلل آلام الجسم والعضلات المصاحبة لنزلات البرد. يساعد على تهدئة الصداع المرتبط بالبرد أو احتقان الجيوب الأنفية. يساهم في تقليل احمرار ودموع العين الناتجة عن الحساسية. يستخدم لتخفيف أعراض الحساسية الموسمية المصحوبة باحتقان وسيلان الأنف.'),
('5-fluorouracil-ebewe 250mg/5ml i.v. vial', 'فلورويوراسيل 250مجم/5مل فيال وريد', 'fluorouracil', 'shanghai xudong haipu pharmaceutical > acdima international trading', 7400, '9088881320685', 'medication', 'yes', 'injection', '250mg', 'antineoplastic', 'يُستخدم في علاج بعض أنواع سرطان القولون والمستقيم ويُعد من الأدوية الأساسية في بروتوكولات العلاج الكيماوي. يُستعمل في علاج سرطان المعدة خاصة في الحالات المتقدمة أو المنتشرة. يدخل ضمن علاج سرطان الثدي مع أدوية كيماوية أخرى لزيادة فعالية العلاج. يمكن استخدامه في علاج سرطان البنكرياس ضمن بروتوكولات العلاج المركب. يُستخدم أحيانًا في علاج سرطان الرأس والرقبة. قد يُعطى لعلاج بعض حالات سرطان الكبد والجهاز الهضمي حسب تقييم الطبيب. يعمل الدواء على إبطاء أو إيقاف نمو الخلايا السرطانية في الجسم.'),
('mooagar sachets', 'مو اجار 2جم اكياس', 'agar', 'hexa pharma company', 7500, '', 'medication', 'yes', 'powder', NULL, 'jaundice', 'الصفراء عند حديثي الولادة يُستخدم كمُليّن طبيعي لعلاج الإمساك، حيث يساعد على زيادة حجم البراز وتسهيل خروجه. يُستعمل في بعض حالات الصفراء (اليرقان) عند الأطفال حديثي الولادة للمساعدة على تحسين حركة الأمعاء وتقليل إعادة امتصاص مادة البيليروبين من الأمعاء. يساعد على زيادة عدد مرات التبرز عند الرضع المصابين بالصفراء، مما يساهم في إخراج البيليروبين مع البراز. قد يُستخدم كعامل مساعد مع الرضاعة والعلاج الضوئي في حالات الصفراء البسيطة عند الأطفال. يدخل في بعض المستحضرات لعلاج اضطرابات الجهاز الهضمي المرتبطة بالإمساك. يعمل على تحسين قوام البراز عند الأطفال والبالغين لأنه غني بالألياف الطبيعية. قد يُستخدم في بعض الأنظمة الغذائية للمساعدة في تنظيم حركة الأمعاء.'),
('limitless lactoferrin 100 mg 30 sachets', 'ليمتلس لاكتوفيرين 100 مجم 30 كيس', 'lactoferrin', 'eva pharma', 48500, '', 'supplement', 'no', 'powder', '100mg', 'iron supplement', 'يساعد في علاج الأنيميا الناتجة عن نقص الحديد لأنه يحسن امتصاص الحديد في الجسم. يساهم في تقوية جهاز المناعة ومقاومة العدوى البكتيرية والفيروسية. يُستخدم كمكمل غذائي في حالات نقص الحديد عند الأطفال والحوامل. يساعد في تقليل التهابات الجهاز الهضمي وتحسين صحة الأمعاء. قد يُستعمل لدعم علاج العدوى البكتيرية والفطرية بفضل خصائصه المضادة للميكروبات. يساهم في تحسين صحة البشرة وتقليل الالتهابات الجلدية في بعض الحالات. يُستخدم أحيانًا لدعم الجسم في حالات الإجهاد وضعف المناعة.'),
('plovimas mouth spray 60 ml', 'بلوفيماس سبراي للفم 60 مل', 'des-infectant formula', NULL, 7900, '', 'personal_care', 'no', 'nasal_spray', '60ml', 'oral care', 'بلوفيماس بخاخ للفم بالفراولة 60 مل يحتوي على عومل ومواد مضادة للجراثيم يعمل على مقاومة الروائح الناتجة بعد الأكل والشرب والتدخين'),
('a1 cream 100 gm', 'ايه وان بيبي كريم 100جم', 'castor oil+zinc oxide+arachis oil+bees wax', 'egpi > egd', 4500, '6223003930479', 'medication', 'yes', 'cream', '100g', 'soothing agent', 'التهابات الحفاضات والتسلخات للأطفال والكبار يُستخدم لتهدئة وعلاج التهابات الجلد البسيطة مثل الاحمرار والتهيج. مفيد في علاج تسلخات الأطفال الناتجة عن الحفاض، حيث يعمل كطبقة واقية على الجلد. يساعد في ترطيب الجلد الجاف وحمايته من التشقق. يُستخدم في حالات حروق الشمس البسيطة والتهيج الناتج عن الحرارة. يساهم في حماية الجلد من الاحتكاك والرطوبة خاصة في المناطق الحساسة. قد يُستعمل للمساعدة في علاج التهابات الجلد السطحية البسيطة. يساعد على تكوين طبقة عازلة على الجلد تقلل فقدان الرطوبة وتحافظ على نعومته.'),
('limitless caffeine 80mg 20 oral dispersible films', 'ليميتلس كافيين 80مجم 20 فيلم', 'caffeine', 'eve pharma', 14500, '6223012483706', 'medication', 'yes', 'tablet', '80mg', 'cns.stimulant.methylxanthine', '- يساعد على زيادة النشاط وتقليل الإحساس بالتعب والإرهاق. - يساعد على تحسين التركيز والانتباه خاصة أثناء المذاكرة أو العمل لفترات طويلة. - قد يستخدم للتقليل من الشعور بالنعاس أثناء القيادة أو العمل الليلي. - يساعد على تنبيه الجهاز العصبي وزيادة اليقظة الذهنية. - يمكن أن يساهم في تحسين الأداء البدني أثناء التمارين الرياضية. - قد يستخدم أحيانًا للمساعدة في تخفيف الصداع المرتبط بالإجهاد أو قلة النوم. - يساعد على تحسين المزاج والشعور بالطاقة والنشاط خلال اليوم.'),
('no cal 300 packets', 'نو كال 300 باكت', 'sucralose+dextrose+maltodextrin', NULL, 34000, '6224000843083', 'medication', 'yes', 'other', NULL, 'sweetner', 'مُحلي خالي من السعرات الحرارية مصنوع من السكرالوز مسحوق أبيض اللون عديم الرائحة والطعم يستخدم لتحلية الأطعمة'),
('canti colin syrup 100 ml', 'كانتي كولين شراب 100 مل', 'citicoline', 'pharma zad > cantreat', 20000, '', 'medication', 'yes', 'syrup', '100ml', 'cerebral circulatory enhancer', '• يساعد في تحسين الذاكرة والتركيز والانتباه في الاطفال والكبار. • يُستخدم في حالات الجلطات الدماغية للمساعدة على استعادة وظائف المخ. • يفيد في علاج ضعف الدورة الدموية في المخ. • يُستعمل في حالات إصابات الرأس والارتجاج لتحسين وظائف المخ. • يساعد في تقليل أعراض الزهايمر وضعف الإدراك. • قد يُستخدم في بعض حالات الشلل أو ضعف الحركة الناتج عن مشاكل المخ. • يساهم في تحسين الانتباه والقدرات الذهنية في حالات الإجهاد الذهني.'),
('abevac 1mg/ml vial', 'ابيفاك 1مجم فيال 1 مل', 'bee venom', 'vacsera', 3800, '', 'vaccine', 'yes', 'injection', '1mg', 'vaccine', 'لقاح سم النحل • يُستخدم لعلاج حساسية لسعات النحل الشديدة وتقليل خطورة حدوث تفاعلات حساسية خطيرة. • يساعد الجسم على تكوين مناعة تدريجية ضد سمّ النحل عند التعرض له لاحقًا. • يُستخدم كعلاج وقائي للأشخاص الذين سبق أن تعرضوا لصدمة تحسسية بسبب لسعة النحل. • يقلل من احتمال حدوث أعراض شديدة مثل تورم الحلق أو ضيق التنفس بعد لسعة النحل. • يُعطى تحت إشراف طبي ضمن برنامج العلاج المناعي للحساسية. • يفيد الأشخاص المعرضين للسعات النحل بشكل متكرر مثل مربي النحل أو العاملين في الزراعة. • يساهم في تقليل شدة التفاعل التحسسي وتحسين أمان المريض عند التعرض للسعات مستقبلًا.'),
('abidec multivitamin drops 25ml', 'ابيديك فيتامين نقط للطفل 25مل', 'multivitamins', 'company', 6000, '5012616173004', 'supplement', 'no', 'drop', '25ml', 'multivitamins', '• يُستخدم لتعويض نقص الفيتامينات عند الأطفال خصوصًا في مرحلة الرضاعة والنمو. • يساعد في دعم النمو الصحي وتقوية الجسم عند الأطفال. • يُستخدم في حالات ضعف الشهية أو سوء التغذية. • يساهم في تقوية المناعة وتقليل فرص الإصابة بالعدوى. • مفيد للأطفال الذين لا يحصلون على احتياجهم من الفيتامينات من الطعام. • يُستخدم أثناء فترات المرض أو النقاهة لتعويض الفيتامينات المفقودة. • يساعد في دعم صحة العظام والجلد والأعصاب بفضل احتوائه على عدة فيتامينات أساسية.'),
('dansetron 4mg /2 ml 5 amp', 'دانسيترون 4مجم/2مل 5 امبولات', 'ondansetron', 'hikma', 7865, '6223005181268', 'medication', 'yes', 'injection', '4mg', 'antiemetic', 'يستخدم لمنع وعلاج الغثيان والقيء والترجيع. يقلل القيء والغثيان بعد العمليات الجراحية والتخدير. يُستعمل في حالات القيء الشديد المرتبط بالعلاج الإشعاعي. يساعد في السيطرة على القيء الشديد في بعض حالات النزلات المعوية. قد يُستخدم لتقليل القيء لدى المرضى الذين يتلقون أدوية قوية تسبب الغثيان. يستعمل أحياناً في الطوارئ للسيطرة على القيء المستمر لمنع الجفاف. قد يصفه الأطباء لبعض حالات القيء الشديد أثناء الحمل تحت إشراف طبي.'),
('abilaxine 5 mg 20 coated tab', 'ابيلاكسين 5مجم 20 قرص', 'bisacodyl', 'glaxo smithkline', 450, '6221045000839', 'medication', 'no', 'tablet', '5mg', 'laxative', '- علاج حالات الإمساك المؤقت وتحفيز حركة الأمعاء. - يُستخدم لتفريغ الأمعاء قبل بعض الفحوصات الطبية مثل منظار القولون. - يساعد في تنظيف القولون قبل العمليات الجراحية الخاصة بالجهاز الهضمي. - يُستعمل في حالات الإمساك الناتج عن قلة الحركة أو تغيير النظام الغذائي. - قد يُستخدم بعد العمليات الجراحية عندما يُنصح بتجنب الشد أثناء التبرز. - يُستعمل أحيانًا في برامج تفريغ الأمعاء تحت إشراف طبي. - يساعد على تنشيط حركة القولون عند الأشخاص الذين يعانون من بطء حركة الأمعاء.'),
('abilaxine 10mg 5 adult supp', 'ابيلاكسين 10 مجم لبوس كبار 5 اقماع', 'bisacodyl', 'glaxo smithkline', 400, '', 'medication', 'no', 'suppository', '10mg', 'laxative', '- علاج حالات الإمساك المؤقت وتحفيز حركة الأمعاء. - يُستخدم لتفريغ الأمعاء قبل بعض الفحوصات الطبية مثل منظار القولون. - يساعد في تنظيف القولون قبل العمليات الجراحية الخاصة بالجهاز الهضمي. - يُستعمل في حالات الإمساك الناتج عن قلة الحركة أو تغيير النظام الغذائي. - قد يُستخدم بعد العمليات الجراحية عندما يُنصح بتجنب الشد أثناء التبرز. - يُستعمل أحيانًا في برامج تفريغ الأمعاء تحت إشراف طبي. - يساعد على تنشيط حركة القولون عند الأشخاص الذين يعانون من بطء حركة الأمعاء.'),
('abilaxine 5mg 5 infantile supp', 'ابيلاكسين 5مجم لبوس اطفال 5 اقماع', 'bisacodyl', 'glaxo smithkline', 320, '6221045000792', 'medication', 'no', 'suppository', '5mg', 'laxative', '- علاج حالات الإمساك المؤقت وتحفيز حركة الأمعاء. - يُستخدم لتفريغ الأمعاء قبل بعض الفحوصات الطبية مثل منظار القولون. - يساعد في تنظيف القولون قبل العمليات الجراحية الخاصة بالجهاز الهضمي. - يُستعمل في حالات الإمساك الناتج عن قلة الحركة أو تغيير النظام الغذائي. - قد يُستخدم بعد العمليات الجراحية عندما يُنصح بتجنب الشد أثناء التبرز. - يُستعمل أحيانًا في برامج تفريغ الأمعاء تحت إشراف طبي. - يساعد على تنشيط حركة القولون عند الأشخاص الذين يعانون من بطء حركة الأمعاء.'),
('abilia 15mg 30 f.c.tabs', 'ابيليا 15مجم 30 قرص', 'aripiprazole', 'chemipharm', 10500, '', 'medication', 'yes', 'tablet', '15mg', 'psychiatric.antipsychotics', '* يستخدم في علاج الفصام (Schizophrenia) وتقليل الهلاوس والضلالات * يساعد في علاج نوبات الهوس المرتبطة باضطراب ثنائي القطب * يُستخدم كمساعد مع مضادات الاكتئاب في حالات الاكتئاب الشديد * يساعد في تقليل التهيج والسلوك العدواني خاصة عند بعض المرضى * يُستخدم في علاج اضطرابات السلوك المرتبطة بالتوحد * يساعد في تحسين التفكير والتركيز وتقليل التوتر النفسي * يعمل على توازن المواد الكيميائية في المخ مثل الدوبامين والسيروتونين'),
